export function resolveDiagramsForConnector(
  connector: string,
  platformId?: string,
): ProcedureImage[] {
  if (platformId === 'whirlpool_duet_sport_dryer') {
    const ids = W8178559_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W8178559_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  const catalog =
    platformId === 'whirlpool_duet_sport'
      ? W8178558_DIAGRAMS
      : W11169652_DIAGRAMS;
  const connectorMap =
    platformId === 'whirlpool_duet_sport'
      ? W8178558_CONNECTOR_DIAGRAM_IDS
      : CONNECTOR_DIAGRAM_IDS;
  const ids = connectorMap[connector] || [];
  return ids
    .map((id) => catalog[id])
    .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
}

export function serializeProcedureImages(images: ProcedureImage[]): ProcedureImage[] {
  return images.map(({ id, caption, assetPath }) => ({ id, caption, assetPath }));
}
